Created the animated SVG and saved it to `./anteater.svg` (`/Users/andie/.local/share/anteater/runs/carbon-native-20261113-195405/runs/high/attempt-11/work/anteater.svg`).

```svg
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 650" width="800" height="650" role="img" aria-label="Animated anteater riding a unicycle while juggling three colorful glass bottles">
  <title>Anteater Riding a Unicycle While Juggling Bottles</title>
  <defs>
    <!-- Sky & Stage Gradients -->
    <linearGradient id="skyGrad" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#BEE3F8"/>
      <stop offset="55%" stop-color="#EBF8FF"/>
      <stop offset="100%" stop-color="#FFF5E4"/>
    </linearGradient>
    <radialGradient id="sunGlow" cx="0.68" cy="0.24" r="0.42">
      <stop offset="0%" stop-color="#FFFBEA" stop-opacity="0.95"/>
      <stop offset="55%" stop-color="#FFEAB6" stop-opacity="0.35"/>
      <stop offset="100%" stop-color="#FFEAB6" stop-opacity="0"/>
    </radialGradient>
    <linearGradient id="hillGrad1" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#C6E2C9"/>
      <stop offset="100%" stop-color="#A8CFAF"/>
    </linearGradient>
    <linearGradient id="hillGrad2" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#AED5B4"/>
      <stop offset="100%" stop-color="#8BB995"/>
    </linearGradient>
    <linearGradient id="groundGrad" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#E6C79C"/>
      <stop offset="18%" stop-color="#D9B382"/>
      <stop offset="100%" stop-color="#BC915E"/>
    </linearGradient>

    <!-- Unicycle Gradients -->
    <linearGradient id="chromeGrad" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="#F8FAFC"/>
      <stop offset="45%" stop-color="#CBD5E1"/>
      <stop offset="75%" stop-color="#64748B"/>
      <stop offset="100%" stop-color="#E2E8F0"/>
    </linearGradient>
    <linearGradient id="frameRed" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stop-color="#EF4444"/>
      <stop offset="50%" stop-color="#DC2626"/>
      <stop offset="100%" stop-color="#991B1B"/>
    </linearGradient>
    <linearGradient id="saddleLeather" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#7C3F1D"/>
      <stop offset="60%" stop-color="#542710"/>
      <stop offset="100%" stop-color="#361707"/>
    </linearGradient>

    <!-- Anteater Fur Gradients -->
    <linearGradient id="bodyFur" x1="0.15" y1="0" x2="0.85" y2="1">
      <stop offset="0%" stop-color="#9A8B7F"/>
      <stop offset="55%" stop-color="#7E7065"/>
      <stop offset="100%" stop-color="#5E5249"/>
    </linearGradient>
    <linearGradient id="headFur" x1="0" y1="0.2" x2="1" y2="0.6">
      <stop offset="0%" stop-color="#96877B"/>
      <stop offset="58%" stop-color="#7A6C61"/>
      <stop offset="88%" stop-color="#4A4039"/>
      <stop offset="100%" stop-color="#332B26"/>
    </linearGradient>
    <linearGradient id="tailBaseGrad" x1="1" y1="0.5" x2="0" y2="0.3">
      <stop offset="0%" stop-color="#786A5F"/>
      <stop offset="45%" stop-color="#594D44"/>
      <stop offset="85%" stop-color="#3F3630"/>
      <stop offset="100%" stop-color="#6E6157"/>
    </linearGradient>
    <linearGradient id="tailHighlightGrad" x1="1" y1="0.6" x2="0" y2="0.2">
      <stop offset="0%" stop-color="#9E8F83"/>
      <stop offset="60%" stop-color="#7A6C62"/>
      <stop offset="100%" stop-color="#C8BDB1"/>
    </linearGradient>
    <linearGradient id="nearLimbFur" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="#98897D"/>
      <stop offset="100%" stop-color="#6F6258"/>
    </linearGradient>
    <linearGradient id="foreArmFur" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#B8ACA0"/>
      <stop offset="65%" stop-color="#96887C"/>
      <stop offset="100%" stop-color="#75685E"/>
    </linearGradient>

    <!-- Bottle Gradients -->
    <linearGradient id="emeraldBottle" x1="0" y1="0" x2="1" y2="0.2">
      <stop offset="0%" stop-color="#34D399"/>
      <stop offset="35%" stop-color="#10B981"/>
      <stop offset="80%" stop-color="#047857"/>
      <stop offset="100%" stop-color="#065F46"/>
    </linearGradient>
    <linearGradient id="amberBottle" x1="0" y1="0" x2="1" y2="0.2">
      <stop offset="0%" stop-color="#FBBF24"/>
      <stop offset="35%" stop-color="#D97706"/>
      <stop offset="80%" stop-color="#92400E"/>
      <stop offset="100%" stop-color="#78350F"/>
    </linearGradient>
    <linearGradient id="rubyBottle" x1="0" y1="0" x2="1" y2="0.2">
      <stop offset="0%" stop-color="#FB7185"/>
      <stop offset="35%" stop-color="#E11D48"/>
      <stop offset="80%" stop-color="#9F1239"/>
      <stop offset="100%" stop-color="#881337"/>
    </linearGradient>
  </defs>

  <style>
    /* Ensure all SVG group transforms pivot around their local (0,0) joint */
    .wheel-spin, .counter-spin,
    .r-thigh, .r-shin, .r-foot,
    .l-thigh, .l-shin, .l-foot,
    .near-upper-arm, .near-fore-arm, .near-paw,
    .far-upper-arm, .far-fore-arm, .far-paw,
    .tail-sway, .tail-tip-sway, .head-bob, .tongue-flick, .tassel-swing,
    .bottle, .ground-scroll, .shadow-pulse, .cloud-drift-1, .cloud-drift-2, .bunting-sway {
      transform-origin: 0px 0px;
    }

    /* Wheel & Pedals (1.2s per revolution, moving right) */
    .wheel-spin {
      animation: spinCW 1.2s linear infinite;
    }
    .counter-spin {
      animation: spinCCW 1.2s linear infinite;
    }
    @keyframes spinCW {
      from { transform: rotate(0deg); }
      to   { transform: rotate(360deg); }
    }
    @keyframes spinCCW {
      from { transform: rotate(0deg); }
      to   { transform: rotate(-360deg); }
    }

    /* Ground zero-slip scroll (circumference ~ 440px per 1.2s) */
    .ground-scroll {
      animation: scrollLeft 1.2s linear infinite;
    }
    @keyframes scrollLeft {
      from { transform: translateX(0px); }
      to   { transform: translateX(-440px); }
    }

    .shadow-pulse {
      animation: shadowPulse 0.6s ease-in-out infinite;
    }
    @keyframes shadowPulse {
      0%, 100% { transform: scale(1, 1); opacity: 0.26; }
