      30%   { transform: translate(587.7px, 170.6px) rotate(319.3deg); }
      35%   { transform: translate(598.0px, 264.0px) rotate(375.0deg); }
      /* Dwell 1: Right Hand scoop */
      40%   { transform: translate(594.0px, 277.0px) rotate(363.0deg); }
      45%   { transform: translate(583.0px, 276.0px) rotate(366.0deg); }
      /* Flight 2: Right Hand (576,258) -> Left Hand (504,268), counter-clockwise flip */
      50%   { transform: translate(576.0px, 258.0px) rotate(375.0deg); }
      55%   { transform: translate(565.7px, 159.0px) rotate(319.3deg); }
      60%   { transform: translate(555.4px, 93.6px)  rotate(263.6deg); }
