      70%   { transform: translate(534.9px, 62.9px)  rotate(152.1deg); }
      75%   { transform: translate(524.6px, 97.8px)  rotate(96.4deg); }
      80%   { transform: translate(514.3px, 166.2px) rotate(40.7deg); }
      85%   { transform: translate(504.0px, 268.0px) rotate(-15.0deg); }
      /* Dwell 2: Left Hand scoop */
